package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen5Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        String input = "abc";
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntity() throws IOException {
        // &#123; -> { (ASCII 123)
        // length: &# (2) + 123 (3) + ; (1) = 6
        String input = "&#123;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityLowercase() throws IOException {
        // &#x7B; -> { (ASCII 123)
        // length: &# (2) + x (1) + 7B (2) + ; (1) = 6
        String input = "&#x7B;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityUppercase() throws IOException {
        // &#X7B; -> {
        // length: &# (2) + X (1) + 7B (2) + ; (1) = 6
        String input = "&#X7B;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_DecimalInvalidFormat() throws IOException {
        // &#abc; -> NumberFormatException -> returns 0
        String input = "&#abc;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_HexInvalidFormat() throws IOException {
        // &#xG1; -> NumberFormatException -> returns 0
        String input = "&#xG1;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_PartialMatchStart() throws IOException {
        // Only '&' at index
        String input = "&abc";
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
    }

    @Test
    public void testTranslate_PartialMatchAmpersand() throws IOException {
        // "&#" but no content
        // Note: This test might throw StringIndexOutOfBoundsException based on the provided source code 
        // because it doesn't check if index+1 or start+1 exists. 
        // However, we follow the logic provided.
        String input = "&#;";
        // In the provided code, input.charAt(start) where start=2 will be ';'
        // then the while loop will immediately terminate because input.charAt(end) == ';'
        // then Integer.parseInt("", 10) will throw NumberFormatException.
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
    }
}
